{"command":"python3 - << 'PY'
maze = open("maze.txt").read().splitlines()
rows = [list(line) for line in maze]
R, C = len(rows), len(rows[0])
# flood fill components of non-wall
comp = [[-1]*C for _ in range(R)]
cid = 0
from collections import deque
dirs = [(-1,0),(1,0),(0,-1),(0,1)]
for i in range(R):
    for j in range(C):
        if rows[i][j] != "#" and comp[i][j] == -1:
            q = deque([(i,j)])
            comp[i][j] = cid
            cells = [(i,j)]
            while q:
                r,c = q.popleft()
                for dr,dc in dirs:
                    nr,nc = r+dr, c+dc
                    if 0<=nr<R and 0<=nc<C and rows[nr][nc] != "#" and comp[nr][nc]==-1:
                        comp[nr][nc]=cid
                        q.append((nr,nc))
                        cells.append((nr,nc))
            print(f"comp {cid}: size {len(cells)} sample {cells[:3]} has@ {any(rows[r][c]=='@' for r,c in cells)} hasE {any(rows[r][c]=='E' for r,c in cells)}")
            cid += 1

# find walls that if removed connect start component to exit component
start_c = comp[1][1]
end_c = comp[23][23]
print("start_c", start_c, "end_c", end_c)
# adjacent wall cells between comps
bridges = []
for i in range(R):
    for j in range(C):
        if rows[i][j] != "#":
            continue
        neigh = set()
        for dr,dc in dirs:
            nr,nc = i+dr, j+dc
            if 0<=nr<R and 0<=nc<C and rows[nr][nc] != "#":
                neigh.add(comp[nr][nc])
        if start_c in neigh and end_c in neigh:
            bridges.append((i,j))
print("direct bridges", bridges)

# also list all components adjacent to start component
adj = {}
for i in range(R):
    for j in range(C):
        if rows[i][j] == "#":
            continue
        for dr,dc in dirs:
            nr,nc = i+dr, j+dc
            if 0<=nr<R and 0<=nc<C and rows[nr][nc]=="#":
                # wall, look beyond? just note wall positions separating
                pass
print("--- maze with comp ids for open ---")
for i in range(R):
    line=""
    for j in range(C):
        if rows[i][j]=="#":
            line += "#"
        else:
            line += str(comp[i][j]%10)
    print(f"{i:2} {line}")
