{"command":"python3 - << 'PY'
rows = open("maze.txt").read().splitlines()
R,C=len(rows),len(rows[0])
start=(1,1)
from collections import deque
q=deque([start]); seen={start}; parent={start:None}
dirs=[("down",1,0),("up",-1,0),("right",0,1),("left",0,-1)]
while q:
    r,c=q.popleft()
    for name,dr,dc in dirs:
        nr,nc=r+dr,c+dc
        if rows[nr][nc]!='#' and (nr,nc) not in seen:
            seen.add((nr,nc)); parent[(nr,nc)]=(r,c,name); q.append((nr,nc))
print("reachable", len(seen))
# cells in start component adjacent to a wall that borders the other component
# Find the sealed cell: a wall whose removal connects start to E
end=(25,25)
def connects(br,bc):
    g=[list(r) for r in rows]
    g[br][bc]='.'
    q=deque([start]); s={start}
    while q:
        r,c=q.popleft()
        if (r,c)==end: return True
        for _,dr,dc in dirs:
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and g[nr][nc]!='#' and (nr,nc) not in s:
                s.add((nr,nc)); q.append((nr,nc))
    return False
seals=[]
for r in range(R):
    for c in range(C):
        if rows[r][c]=='#' and connects(r,c):
            seals.append((r,c))
print("single-cell seals that connect", seals)
# farthest reachable from start by BFS distance
dist={start:0}
q=deque([start])
while q:
    r,c=q.popleft()
    for name,dr,dc in dirs:
        nr,nc=r+dr,c+dc
        if (nr,nc) in seen and (nr,nc) not in dist:
            dist[(nr,nc)]=dist[(r,c)]+1
            q.append((nr,nc))
far=max(dist, key=dist.get)
print("farthest", far, dist[far])
# print path to each cell adjacent to each seal
for br,bc in seals:
    print("seal", br,bc)
    for name,dr,dc in dirs:
        nr,nc=br-dr, bc-dc  # cell from which moving `name` hits the seal? 
    for name,dr,dc in dirs:
        nr,nc=br+dr,bc+dc
        if (nr,nc) in seen:
            # path
            path=[]
            cur=(nr,nc)
            while cur!=start:
                pr,pc,nm=parent[cur]
                path.append(nm)
                cur=(pr,pc)
            path.reverse()
            print("  approach from", (nr,nc), "dir into seal would be", 
                  [n for n,dr,dc in dirs if (nr+dr,nc+dc)==(br,bc)], "pathlen", len(path))
            print("  "+" ".join(path))
