{"command":"cp maze_backup.txt maze.txt && python3 - << 'PY'
rows = [list(line) for line in open("maze.txt").read().splitlines()]
R,C=len(rows),len(rows[0])
# flood from start and from E, find walls that border both components (potential doors)
from collections import deque
def flood(sr,sc):
    seen={(sr,sc)}
    q=deque([(sr,sc)])
    while q:
        r,c=q.popleft()
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and rows[nr][nc]!="#" and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    return seen
S=flood(1,1)
E=flood(25,25)
print("S",len(S),"E",len(E))
# walls adjacent to both
cands=[]
for r in range(R):
    for c in range(C):
        if rows[r][c]!="#":
            continue
        neigh=set()
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr,nc=r+dr,c+dc
            if (nr,nc) in S: neigh.add("S")
            if (nr,nc) in E: neigh.add("E")
        if neigh=={"S","E"}:
            cands.append((r,c))
print("bridge walls", cands)
# also walls adjacent to S and some other open not in S
other=set()
for r in range(R):
    for c in range(C):
        if rows[r][c]!="#" and (r,c) not in S:
            other.add((r,c))
