import subprocess
from pathlib import Path
from collections import deque

def load():
    maze = Path("maze.txt").read_text().splitlines()
    return maze

def pos(maze):
    return next((i,j) for i,r in enumerate(maze) for j,c in enumerate(r) if c=="@")

dirs = {"up":(-1,0),"down":(1,0),"left":(0,-1),"right":(0,1)}
opp = {"up":"down","down":"up","left":"right","right":"left"}

def path_between(maze, start, goal):
    rows, cols = len(maze), len(maze[0])
    q = deque([start]); prev = {start: None}
    while q:
        r,c = q.popleft()
        if (r,c)==goal:
            break
        for n,(dr,dc) in dirs.items():
            nr,nc = r+dr,c+dc
            if 0<=nr<rows and 0<=nc<cols and maze[nr][nc] != "#" and (nr,nc) not in prev:
                prev[(nr,nc)] = ((r,c), n)
                q.append((nr,nc))
    if goal not in prev:
        return None
    path=[]
    cur=goal
    while cur!=start:
        p,n = prev[cur]
        path.append(n)
        cur=p
    path.reverse()
    return path

def move(seq):
    if not seq:
        return
    r = subprocess.run(["./move.py", *seq], capture_output=True, text=True)
    return r.stdout.splitlines()[0]

maze = load()
rows, cols = len(maze), len(maze[0])
start = pos(maze)
# component
q=deque([start]); seen={start}
while q:
    r,c=q.popleft()
    for n,(dr,dc) in dirs.items():
        nr,nc=r+dr,c+dc
        if 0<=nr<rows and 0<=nc<cols and maze[nr][nc]!="#" and (nr,nc) not in seen:
            seen.add((nr,nc)); q.append((nr,nc))

# candidate wall probes: from a seen cell, direction into #
probes=[]
for r,c in seen:
    for n,(dr,dc) in dirs.items():
        nr,nc=r+dr,c+dc
        if 0<=nr<rows and 0<=nc<cols and maze[nr][nc]=="#":
            probes.append(((r,c), n, (nr,nc)))
print("probes", len(probes), "component", len(seen))

# We'll walk efficiently: current position, path to probe cell, try direction, if blocked stay, continue.
cur = pos(load())
passed=[]
for i,((r,c), n, wall) in enumerate(probes):
    maze = load()
    cur = pos(maze)
    p = path_between(maze, cur, (r,c))
    if p is None:
        print("cannot reach probe", (r,c), "from", cur)
        break
    line = move(p + [n])
    # parse moved count
    # "Moved X square(s)."
    moved = int(line.split()[1])
    expected_open = len(p)
    if moved > expected_open:
        passed.append(((r,c), n, wall, line))
        print("PASSED", (r,c), n, wall, line)
        break
    if i % 50 == 0:
        print(f"checked {i}/{len(probes)} last {line}")
else:
    print("no passable wall in start component")
print("passed", passed)
print("final", pos(load()))
