# compare a few maze.txt contents hashes and whether they have a path
from collections import deque
def has_path(text):
    lines=text.splitlines()
    if not lines: return None
    rows=[list(l) for l in lines if l]
    if not rows: return None
    R,C=len(rows),len(rows[0])
    try:
        start=next((i,j) for i,r in enumerate(rows) for j,ch in enumerate(r) if ch=="@")
        goal=next((i,j) for i,r in enumerate(rows) for j,ch in enumerate(r) if ch=="E")
    except StopIteration:
        return "no markers"
    q=deque([start]); seen={start}
    while q:
        r,c=q.popleft()
        if (r,c)==goal: return True
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<len(rows[nr]) and rows[nr][nc]!="#" and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    return False
hashes=collections.Counter()
examples={}
for dirpath, dirs, files in os.walk(root):
    if "maze.txt" in files:
        p=os.path.join(dirpath,"maze.txt")
        try:
            t=open(p).read()
        except Exception as e:
            continue
        h=hashlib.sha256(t.encode()).hexdigest()[:10]
        hashes[h]+=1
        examples.setdefault(h, (p, has_path(t), len(t)))
print("unique mazes", len(hashes))
for h,c in hashes.most_common(20):
    print(c, h, examples[h])
